import{_ as o,l as i,o as e,c,v as n,p as s,x as r,d as l,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"runc 与 containerd","description":"","frontmatter":{"title":"runc 与 containerd","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/container-runtime.md","filePath":"cs/container-runtime.md","lastUpdated":1789023840000}'),u={name:"cs/container-runtime.md"};function m(h,a,f,_,C,g){const t=i("Mermaid");return e(),c("div",null,[a[1]||(a[1]=n('<h1 id="runc-与-containerd" tabindex="-1">runc 与 containerd <a class="header-anchor" href="#runc-与-containerd" aria-label="Permalink to &quot;runc 与 containerd&quot;">​</a></h1><div class="epigraph"><p>runc 按 OCI 配置把进程放进命名空间与 cgroup；containerd 管镜像、监督、shim，真正的隔离仍是内核原语。</p><footer>—— 据 OCI Runtime Spec；containerd 文档；[namespaces](/cs/namespaces) 与 [cgroups](/cs/cgroups) 为先修</footer></div><p><a href="/cs/nested-virtualization">上一课</a>是套 VM。<a href="/cs/overlayfs">overlay</a> 已有层。缺口是 <strong>运行时</strong>：runc 如何 <code>clone</code>，containerd 如何盯着它。不是 Docker 产品史。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OCI config.json：rootfs、ns、cap、mount。runc：创建 ns、写 cgroup、exec 用户 pid 1。containerd：拉镜像、快照、调 runc、shim 收 SIGCHLD。缺口：与 <a href="/cs/systemd-units">systemd</a> cgroup 驱动；与 <a href="/cs/netns-veth">netns veth</a>。本课不把 k8s CRI 写成编排课。</p><p><span class="marginnote">shim 让 daemon 升级不杀容器。对象是用户态拼内核隔离，不是新内核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>unpack 层到 overlay → 生成 spec → runc start。对照 <a href="/cs/kvm-qemu">QEMU</a>：一个进 VMX，一个进 ns。对照 <a href="/cs/fuse">FUSE</a>：rootfs 通常是普通 FS。对照 LSM：可带 SELinux 标签。</p>',8)),(e(),s(p,null,{default:r(()=>[d(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IMG%5B%22%E9%95%9C%E5%83%8F%E5%BF%AB%E7%85%A7%22%5D%20--%3E%20SPEC%5B%22OCI%20config%22%5D%0A%20%20SPEC%20--%3E%20RUNC%5B%22clone%20ns%20%2B%20cgroup%22%5D%0A%20%20RUNC%20--%3E%20PID1%5B%22%E5%AE%B9%E5%99%A8%E5%86%85%20init%22%5D%0A%20%20CT%5B%22containerd%22%5D%20--%3E%20RUNC%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>容器运行时把已有内核隔离收成可复现的 JSON，使打包与云调度成为可能。安全等于内核+配置，不是 runc 魔法。不要写成 Docker 教程。与 <a href="/cs/linux-capabilities">capabilities</a>：spec 里 drop。与 <a href="/cs/memcg">memcg</a>：这里落地。</p><p>逃逸往往是内核漏洞或错误特权，不是「容器不是 VM」口号能挡的。</p><p>实现上：spec 里的 mounts 把 proc/sys 以安全选项挂上，漏了就会看到宿主。shim 的父进程若是 containerd，升级 daemon 不杀容器。cgroup 路径决定统计落在哪。 读法上只引用<a href="/cs/nested-virtualization">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>runc 与 containerd</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 runtime hook。不保证 Windows 容器。下一课镜像层格式。</p><p>版本字段会变，课序钉的是机制对象「runc 与 containerd」，不是某一主线内核的结构体名。 后课默认：runc 用 ns/cgroup 启进程。OCI 层如何叠，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>runc 应用 OCI spec；containerd 管镜像与监督。</li><li>隔离来自内核，运行时只拼装。</li><li>OCI 镜像层是下一课。</li><li>出处：OCI runtime；containerd；namespaces。</li></ul>',11))])}const k=o(u,[["render",m]]);export{S as __pageData,k as default};
